import 'package:flutter/material.dart';class FuturisticLineChart extends StatelessWidget{final List<double> values;final Color color;const FuturisticLineChart({super.key,required this.values,this.color=const Color(0xFF00E5A0)});@override Widget build(BuildContext c)=>SizedBox(height:190,child:CustomPaint(painter:_P(values,color)));}class _P extends CustomPainter{final List<double> v;final Color col;_P(this.v,this.col);@override void paint(Canvas c,Size s){if(v.length<2)return;final mn=v.reduce((a,b)=>a<b?a:b),mx=v.reduce((a,b)=>a>b?a:b),r=(mx-mn).abs()<.001?1:mx-mn;final pts=List.generate(v.length,(i)=>Offset(i*s.width/(v.length-1),s.height-15-(v[i]-mn)/r*(s.height-30)));final path=Path()..moveTo(pts[0].dx,pts[0].dy);for(int i=1;i<pts.length;i++){final a=pts[i-1],b=pts[i],m=(a.dx+b.dx)/2;path.cubicTo(m,a.dy,m,b.dy,b.dx,b.dy);}c.drawPath(path,Paint()..color=col.withOpacity(.22)..strokeWidth=12..style=PaintingStyle.stroke..maskFilter=const MaskFilter.blur(BlurStyle.normal,7));c.drawPath(path,Paint()..color=col..strokeWidth=3..style=PaintingStyle.stroke);for(final p in pts)c.drawCircle(p,4,Paint()..color=col);}@override bool shouldRepaint(covariant _P o)=>true;}